// Nmap NSE Script Reference Database
// Comprehensive reference for Nmap Scripting Engine scripts
export const NMAP_SCRIPTS_DB = [
  // ===== HTTP SCRIPTS =====
  { name: 'http-enum', category: 'discovery', service: 'HTTP', description: 'Enumerates directories used by popular web applications and servers by testing for known paths like /admin, /phpmyadmin, /wp-admin, /manager, and hundreds more.', usage: 'nmap -sV --script http-enum -p 80,443 <target>', args: ['http-enum.basepath - base path to prepend (default /)', 'http-enum.displayall - show all status codes not just 200/301/302'], exampleOutput: '| http-enum:\n|   /admin/: Possible admin folder\n|   /phpmyadmin/: phpMyAdmin\n|   /robots.txt: Robots file\n|_  /server-status/: Apache server-status', whenToUse: 'Initial web application reconnaissance to discover hidden directories, admin panels, and common application paths.' },
  { name: 'http-headers', category: 'discovery', service: 'HTTP', description: 'Performs a HEAD request and displays HTTP response headers. Useful for identifying server software, security headers, and misconfigurations.', usage: 'nmap -sV --script http-headers -p 80,443 <target>', args: ['http-headers.path - path to request (default /)'], exampleOutput: '| http-headers:\n|   Server: Apache/2.4.41 (Ubuntu)\n|   X-Powered-By: PHP/7.4.3\n|   X-Frame-Options: DENY\n|_  Content-Security-Policy: default-src self', whenToUse: 'Check for security header presence, identify server software and version, discover information leakage through headers.' },
  { name: 'http-methods', category: 'default', service: 'HTTP', description: 'Finds what HTTP methods are supported by the server by sending an OPTIONS request. Identifies potentially dangerous methods like PUT, DELETE, TRACE, and CONNECT.', usage: 'nmap -sV --script http-methods -p 80,443 <target>', args: ['http-methods.url-path - path to check (default /)', 'http-methods.test-all - test each method individually'], exampleOutput: '| http-methods:\n|   Supported Methods: GET HEAD POST OPTIONS PUT DELETE\n|_  Potentially risky methods: PUT DELETE', whenToUse: 'Check for dangerous HTTP methods enabled on web servers. PUT and DELETE can allow file upload/deletion. TRACE can enable XST attacks.' },
  { name: 'http-robots.txt', category: 'default', service: 'HTTP', description: 'Checks for and parses the robots.txt file, which often reveals hidden directories and admin paths that site owners want to keep from search engines.', usage: 'nmap -sV --script http-robots.txt -p 80,443 <target>', args: [], exampleOutput: '| http-robots.txt:\n|   /admin/\n|   /backup/\n|   /config/\n|_  /internal/', whenToUse: 'Quick passive reconnaissance to discover hidden paths. Often reveals admin panels, backup directories, and internal tools.' },
  { name: 'http-shellshock', category: 'vuln', service: 'HTTP', description: 'Tests web servers for the Shellshock vulnerability (CVE-2014-6271) by sending a crafted User-Agent header containing a bash function definition to CGI scripts.', usage: 'nmap -sV --script http-shellshock --script-args uri=/cgi-bin/test.cgi -p 80 <target>', args: ['uri - CGI script path to test', 'cmd - command to execute if vulnerable (default id)', 'header - HTTP header to inject into (default User-Agent)'], exampleOutput: '| http-shellshock:\n|   VULNERABLE:\n|   HTTP Shellshock vulnerability\n|     State: VULNERABLE\n|     Disclosure date: 2014-09-24\n|_    uid=33(www-data) gid=33(www-data)', whenToUse: 'Test web servers running CGI scripts for Shellshock (Bash bug). Common on older Linux servers with /cgi-bin/ directories.' },
  { name: 'http-sql-injection', category: 'vuln', service: 'HTTP', description: 'Spiders a web server looking for URLs containing queries vulnerable to SQL injection by appending SQL syntax and analyzing error responses.', usage: 'nmap -sV --script http-sql-injection -p 80,443 <target>', args: ['http-sql-injection.url - specific URL to test', 'http-sql-injection.errorstrings - custom error strings file'], exampleOutput: '| http-sql-injection:\n|   Possible sqli for queries:\n|_    http://target/items.php?id=1 with parameter id', whenToUse: 'Quick automated SQL injection detection during web application testing. Not as thorough as sqlmap but useful for initial scanning.' },
  { name: 'http-wordpress-enum', category: 'discovery', service: 'HTTP', description: 'Enumerates WordPress installations including themes, plugins, and timthumbs. Can identify outdated or vulnerable WordPress components.', usage: 'nmap -sV --script http-wordpress-enum -p 80,443 <target>', args: ['http-wordpress-enum.root - base path of WordPress install', 'http-wordpress-enum.search-limit - max pages to search (default 100)', 'http-wordpress-enum.type - what to enumerate: plugins, themes, timthumbs, all'], exampleOutput: '| http-wordpress-enum:\n|   Search limited to top 100 themes/plugins\n|   plugins:\n|     akismet 4.1.3\n|     contact-form-7 5.3.2\n|   themes:\n|     twentytwenty 1.6\n|_    flavor 1.0', whenToUse: 'Enumerate WordPress sites for installed plugins and themes. Cross-reference with known vulnerabilities for each component version.' },
  { name: 'http-php-version', category: 'discovery', service: 'HTTP', description: 'Attempts to retrieve PHP version from a web server by querying special pages like ?=PHPB8B5F2A0-3C92-11d3-A3A9-4C7B08C10000 which displays the PHP credits page on misconfigured servers.', usage: 'nmap -sV --script http-php-version -p 80,443 <target>', args: [], exampleOutput: '| http-php-version:\n|_  PHP version from header: PHP/7.4.3', whenToUse: 'Identify PHP version for vulnerability assessment. Some Easter egg URLs reveal full PHP info on misconfigured servers.' },
  { name: 'http-title', category: 'default', service: 'HTTP', description: 'Shows the title of the default page of a web server. Quick way to identify what application is running on each web port.', usage: 'nmap -sV --script http-title -p 80,443 <target>', args: ['http-title.url - URL to fetch title from'], exampleOutput: '| http-title:\n|_  Apache2 Ubuntu Default Page', whenToUse: 'Quick identification of web applications across many hosts. Useful for large-scale scanning to categorize web servers.' },
  { name: 'http-vuln-cve2017-5638', category: 'vuln', service: 'HTTP', description: 'Detects Apache Struts 2 REST Plugin XStream RCE vulnerability (CVE-2017-5638) which allows remote code execution via crafted Content-Type header.', usage: 'nmap -sV --script http-vuln-cve2017-5638 -p 80,443 <target>', args: ['http-vuln-cve2017-5638.path - path to test (default /)'], exampleOutput: '| http-vuln-cve2017-5638:\n|   VULNERABLE:\n|   Apache Struts Remote Code Execution\n|_    State: VULNERABLE', whenToUse: 'Test for Apache Struts vulnerability that was exploited in the Equifax breach. Check any server running Java web applications.' },
  { name: 'http-git', category: 'discovery', service: 'HTTP', description: 'Checks for an exposed .git directory on a web server. An exposed Git repository can leak source code, credentials, and configuration files.', usage: 'nmap -sV --script http-git -p 80,443 <target>', args: ['http-git.root - base path to check'], exampleOutput: '| http-git:\n|   .git/HEAD is accessible\n|   .git/config has remote URL\n|_  Repository: https://github.com/org/repo.git', whenToUse: 'Check for accidentally exposed .git directories which can leak entire source code repositories and history.' },
  { name: 'http-config-backup', category: 'discovery', service: 'HTTP', description: 'Checks for common configuration backup files like web.config.bak, .htaccess.bak, config.php.bak, etc. that may contain sensitive information.', usage: 'nmap -sV --script http-config-backup -p 80,443 <target>', args: [], exampleOutput: '| http-config-backup:\n|   /web.config.bak - 200 OK\n|_  /.htaccess.old - 200 OK', whenToUse: 'Look for backup configuration files that may expose database credentials, API keys, or internal paths.' },
  { name: 'http-cors', category: 'discovery', service: 'HTTP', description: 'Tests web servers for CORS (Cross-Origin Resource Sharing) misconfigurations by sending requests with different Origin headers and analyzing the Access-Control-Allow-Origin response.', usage: 'nmap -sV --script http-cors -p 80,443 <target>', args: ['http-cors.origin - origin to test with'], exampleOutput: '| http-cors:\n|   Access-Control-Allow-Origin: *\n|   Access-Control-Allow-Credentials: true\n|_  CORS misconfiguration: wildcard with credentials', whenToUse: 'Test for CORS misconfigurations that could allow cross-origin data theft. Wildcard origin with credentials is especially dangerous.' },
  { name: 'http-xssed', category: 'vuln', service: 'HTTP', description: 'Checks if the target host is listed in the xssed.com database of sites with reported cross-site scripting (XSS) vulnerabilities.', usage: 'nmap -sV --script http-xssed -p 80,443 <target>', args: [], exampleOutput: '| http-xssed:\n|   Found 3 XSS reports:\n|_  http://xssed.com/mirror/12345/', whenToUse: 'Quick check if a target has been reported for XSS vulnerabilities in public databases.' },
  { name: 'http-waf-detect', category: 'discovery', service: 'HTTP', description: 'Attempts to determine whether a web server is behind a Web Application Firewall (WAF) by sending potentially malicious requests and analyzing the responses.', usage: 'nmap -sV --script http-waf-detect -p 80,443 <target>', args: ['http-waf-detect.detectBodyChanges - detect WAF through body changes', 'http-waf-detect.uri - URI to test'], exampleOutput: '| http-waf-detect:\n|_  IDS/IPS/WAF detected: Cloudflare', whenToUse: 'Identify WAF/IPS protection before attempting web application testing. Helps determine which bypass techniques to use.' },
  { name: 'http-waf-fingerprint', category: 'discovery', service: 'HTTP', description: 'Tries to detect and identify the Web Application Firewall (WAF) by fingerprinting response headers, cookies, and error page signatures.', usage: 'nmap -sV --script http-waf-fingerprint -p 80,443 <target>', args: ['http-waf-fingerprint.intensive - try more probes (slower)'], exampleOutput: '| http-waf-fingerprint:\n|   Detected WAF: ModSecurity\n|_  Version: 2.9.3', whenToUse: 'Identify specific WAF product and version to research known bypasses and adjust testing methodology.' },
  { name: 'http-sitemap-generator', category: 'discovery', service: 'HTTP', description: 'Spiders the web server and generates a simple sitemap showing the directory structure and page layout of the application.', usage: 'nmap -sV --script http-sitemap-generator -p 80,443 <target>', args: ['http-sitemap-generator.url - starting URL', 'httpspider.maxpagecount - max pages to crawl'], exampleOutput: '| http-sitemap-generator:\n|   /\n|   /about/\n|   /login/\n|   /api/v1/\n|_  /admin/', whenToUse: 'Map the structure of a web application. Useful for identifying all accessible endpoints during initial reconnaissance.' },
  { name: 'http-slowloris-check', category: 'vuln', service: 'HTTP', description: 'Tests whether the web server is vulnerable to the Slowloris denial-of-service attack by opening connections and sending partial HTTP headers slowly.', usage: 'nmap -sV --script http-slowloris-check -p 80 <target>', args: [], exampleOutput: '| http-slowloris-check:\n|   VULNERABLE:\n|   Slowloris DOS attack\n|_    State: LIKELY VULNERABLE', whenToUse: 'Test if a web server is vulnerable to Slowloris DoS. Apache without mod_reqtimeout is typically vulnerable.' },

  // ===== SMB SCRIPTS =====
  { name: 'smb-enum-shares', category: 'discovery', service: 'SMB', description: 'Enumerates SMB shares on a Windows system, showing share names, types, comments, and access permissions for the current user.', usage: 'nmap -sV --script smb-enum-shares -p 445 <target>', args: ['smbusername - username for auth', 'smbpassword - password for auth', 'smbdomain - domain for auth'], exampleOutput: '| smb-enum-shares:\n|   ADMIN$ - Remote Admin (admin only)\n|   C$ - Default share (admin only)\n|   IPC$ - Remote IPC\n|   Users - (read access)\n|_  Backups - (read/write access)', whenToUse: 'Enumerate accessible SMB shares. Look for shares with read/write access that may contain sensitive data, credentials, or allow file upload.' },
  { name: 'smb-enum-users', category: 'discovery', service: 'SMB', description: 'Enumerates users on a Windows system through SMB using SAMR enumeration or LSA lookups. Requires at least anonymous or guest access.', usage: 'nmap -sV --script smb-enum-users -p 445 <target>', args: ['smbusername - username for auth', 'smbpassword - password for auth', 'smbdomain - domain for auth'], exampleOutput: '| smb-enum-users:\n|   Administrator (RID: 500)\n|   Guest (RID: 501, disabled)\n|   svc_backup (RID: 1001)\n|_  john.doe (RID: 1002)', whenToUse: 'Enumerate domain or local user accounts via SMB. Useful for building a target user list for password spraying or kerberoasting.' },
  { name: 'smb-vuln-ms17-010', category: 'vuln', service: 'SMB', description: 'Tests for the EternalBlue SMB vulnerability (MS17-010/CVE-2017-0144) used by WannaCry and NotPetya. Checks if the SMBv1 server is vulnerable without exploiting it.', usage: 'nmap -sV --script smb-vuln-ms17-010 -p 445 <target>', args: [], exampleOutput: '| smb-vuln-ms17-010:\n|   VULNERABLE:\n|   Remote Code Execution vulnerability in Microsoft SMBv1\n|     State: VULNERABLE\n|     Risk factor: HIGH\n|     CVE: CVE-2017-0144', whenToUse: 'Critical vulnerability check. MS17-010 is one of the most exploited vulnerabilities. Check all Windows systems with SMB exposed.' },
  { name: 'smb-vuln-ms08-067', category: 'vuln', service: 'SMB', description: 'Tests for the MS08-067 vulnerability (CVE-2008-4250) in the Windows Server service that allows remote code execution. Used by the Conficker worm.', usage: 'nmap -sV --script smb-vuln-ms08-067 -p 445 <target>', args: [], exampleOutput: '| smb-vuln-ms08-067:\n|   VULNERABLE:\n|   Microsoft Windows system vulnerable to remote code execution\n|_    State: VULNERABLE', whenToUse: 'Test very old Windows systems (XP, Server 2003, Server 2008 pre-patch) for this classic RCE vulnerability.' },
  { name: 'smb-os-discovery', category: 'default', service: 'SMB', description: 'Determines the operating system, computer name, domain, workgroup, and current time over SMB protocol. Works even without authentication.', usage: 'nmap -sV --script smb-os-discovery -p 445 <target>', args: [], exampleOutput: '| smb-os-discovery:\n|   OS: Windows Server 2019 Standard 17763\n|   Computer name: DC01\n|   Domain name: corp.local\n|   FQDN: DC01.corp.local\n|_  System time: 2024-01-15T10:30:00-05:00', whenToUse: 'Identify Windows OS version, computer name, and domain membership. Essential for initial network reconnaissance.' },
  { name: 'smb-brute', category: 'brute', service: 'SMB', description: 'Attempts to brute force SMB login credentials using username/password lists. Tests common and custom credential combinations.', usage: 'nmap -sV --script smb-brute -p 445 <target>', args: ['userdb - username list file', 'passdb - password list file', 'smbdomain - domain to authenticate against'], exampleOutput: '| smb-brute:\n|   Valid credentials:\n|     admin:password123 - Valid credentials\n|_    guest: - Valid credentials (no password)', whenToUse: 'Test for weak SMB credentials. Use targeted wordlists. Be aware of account lockout policies.' },
  { name: 'smb-enum-domains', category: 'discovery', service: 'SMB', description: 'Enumerates domains, along with password policies, on a SMB server. Shows minimum password length, lockout threshold, and password complexity requirements.', usage: 'nmap -sV --script smb-enum-domains -p 445 <target>', args: [], exampleOutput: '| smb-enum-domains:\n|   CORP\n|     Groups: n/a\n|     Users: Administrator, Guest, krbtgt\n|     Password policy:\n|       Minimum password length: 8\n|       Lockout threshold: 5\n|       Password complexity: Enabled', whenToUse: 'Discover domain password policies before attempting brute force or password spraying to avoid lockouts.' },
  { name: 'smb-enum-sessions', category: 'discovery', service: 'SMB', description: 'Enumerates active SMB sessions on a system, showing which users are currently logged in and from which IP addresses.', usage: 'nmap -sV --script smb-enum-sessions -p 445 <target>', args: [], exampleOutput: '| smb-enum-sessions:\n|   Users logged in:\n|     CORP\\admin from 10.0.0.50\n|_    CORP\\john.doe from 10.0.0.100', whenToUse: 'Identify active user sessions to determine which accounts are in use and from which workstations.' },
  { name: 'smb-enum-processes', category: 'discovery', service: 'SMB', description: 'Enumerates running processes on a Windows host via SMB. Requires admin credentials. Shows process names and PIDs.', usage: 'nmap -sV --script smb-enum-processes --script-args smbusername=admin,smbpassword=pass -p 445 <target>', args: ['smbusername', 'smbpassword'], exampleOutput: '| smb-enum-processes:\n|   PID  Process\n|   4    System\n|   440  csrss.exe\n|   504  wininit.exe\n|   692  svchost.exe\n|_  1024 MsMpEng.exe', whenToUse: 'Identify running processes including security software (AV, EDR) to plan evasion strategies.' },
  { name: 'smb-vuln-cve-2017-7494', category: 'vuln', service: 'SMB', description: 'Tests for Samba vulnerability CVE-2017-7494 (SambaCry) which allows remote code execution on Linux/Unix systems running vulnerable Samba versions with a writable share.', usage: 'nmap -sV --script smb-vuln-cve-2017-7494 -p 445 <target>', args: [], exampleOutput: '| smb-vuln-cve-2017-7494:\n|   VULNERABLE:\n|   Samba Remote Code Execution (SambaCry)\n|_    Versions: 3.5.0 - 4.6.4', whenToUse: 'Test Linux/Unix systems running Samba for this RCE vulnerability. Requires a writable share to be exploitable.' },
  { name: 'smb-protocols', category: 'discovery', service: 'SMB', description: 'Determines the SMB protocol versions supported by the target, including SMBv1, SMBv2, and SMBv3. SMBv1 is considered insecure.', usage: 'nmap -sV --script smb-protocols -p 445 <target>', args: [], exampleOutput: '| smb-protocols:\n|   dialects:\n|     NT LM 0.12 (SMBv1)\n|     2.0.2\n|     2.1\n|     3.0\n|_    3.1.1', whenToUse: 'Check if SMBv1 is still enabled. SMBv1 should be disabled as it is vulnerable to many exploits including EternalBlue.' },
  { name: 'smb-security-mode', category: 'default', service: 'SMB', description: 'Returns information about the SMB security level, including whether message signing is enabled, required, or disabled.', usage: 'nmap -sV --script smb-security-mode -p 445 <target>', args: [], exampleOutput: '| smb-security-mode:\n|   account_used: <blank>\n|   authentication_level: user\n|   challenge_response: supported\n|_  message_signing: disabled', whenToUse: 'Check if SMB signing is disabled, which allows NTLM relay attacks. Message signing should be required on domain controllers.' },

  // ===== SSH SCRIPTS =====
  { name: 'ssh-brute', category: 'brute', service: 'SSH', description: 'Performs brute force password guessing against SSH servers using username and password lists.', usage: 'nmap -sV --script ssh-brute -p 22 <target>', args: ['userdb - username wordlist', 'passdb - password wordlist', 'ssh-brute.timeout - connection timeout'], exampleOutput: '| ssh-brute:\n|   Accounts:\n|     root:toor - Valid credentials\n|_    admin:admin123 - Valid credentials', whenToUse: 'Test SSH servers for weak credentials. Use with caution due to account lockout risks. Consider using fail2ban detection.' },
  { name: 'ssh-auth-methods', category: 'default', service: 'SSH', description: 'Returns the authentication methods that an SSH server supports, such as password, publickey, keyboard-interactive, or hostbased.', usage: 'nmap -sV --script ssh-auth-methods -p 22 <target>', args: ['ssh.user - username to check methods for'], exampleOutput: '| ssh-auth-methods:\n|   Supported authentication methods:\n|     publickey\n|     password\n|_    keyboard-interactive', whenToUse: 'Determine if password authentication is enabled (should be disabled in favor of key-based auth) and what methods are available.' },
  { name: 'ssh2-enum-algos', category: 'discovery', service: 'SSH', description: 'Reports the number of algorithms that the target SSH2 server offers for key exchange, encryption, MAC, and compression. Identifies weak algorithms.', usage: 'nmap -sV --script ssh2-enum-algos -p 22 <target>', args: [], exampleOutput: '| ssh2-enum-algos:\n|   kex_algorithms: (10)\n|     diffie-hellman-group14-sha256\n|     ecdh-sha2-nistp256\n|   encryption_algorithms: (6)\n|     aes128-ctr\n|     aes256-ctr\n|     chacha20-poly1305\n|   mac_algorithms: (5)\n|     hmac-sha2-256\n|_    hmac-sha2-512', whenToUse: 'Audit SSH server algorithms for weak ciphers and key exchange methods. Identify deprecated algorithms like diffie-hellman-group1-sha1 or arcfour.' },
  { name: 'ssh-hostkey', category: 'default', service: 'SSH', description: 'Shows SSH hostkeys and their fingerprints. Useful for host verification, detecting changed keys (MITM), or inventory purposes.', usage: 'nmap -sV --script ssh-hostkey -p 22 <target>', args: ['ssh_hostkey - type of output: full, fingerprint, visual, all'], exampleOutput: '| ssh-hostkey:\n|   2048 SHA256:abc123... (RSA)\n|   256 SHA256:def456... (ECDSA)\n|_  256 SHA256:ghi789... (ED25519)', whenToUse: 'Collect SSH host key fingerprints for inventory and MITM detection. Compare against known-good keys.' },
  { name: 'ssh-publickey-acceptance', category: 'auth', service: 'SSH', description: 'Tests whether the SSH server accepts a specific public key for authentication. Used to test if found SSH keys grant access to the target.', usage: 'nmap -sV --script ssh-publickey-acceptance --script-args="ssh.publickey=id_rsa.pub,ssh.user=root" -p 22 <target>', args: ['ssh.publickey - public key file to test', 'ssh.user - username to test with'], exampleOutput: '| ssh-publickey-acceptance:\n|   root: Key accepted\n|_  Authenticated successfully', whenToUse: 'Test if SSH private keys found during an engagement grant access to other systems.' },

  // ===== FTP SCRIPTS =====
  { name: 'ftp-anon', category: 'default', service: 'FTP', description: 'Checks if an FTP server allows anonymous logins. If anonymous access is permitted, lists the contents of the root directory.', usage: 'nmap -sV --script ftp-anon -p 21 <target>', args: ['ftp-anon.maxlist - max files to list'], exampleOutput: '| ftp-anon: Anonymous FTP login allowed (FTP code 230)\n|   -rw-r--r--    1 ftp      ftp          1024 Jan 01  2024 backup.tar.gz\n|_  drwxr-xr-x    2 ftp      ftp          4096 Jan 01  2024 pub', whenToUse: 'Check if anonymous FTP access is enabled. Anonymous FTP can expose sensitive files, backups, or allow file upload.' },
  { name: 'ftp-bounce', category: 'default', service: 'FTP', description: 'Checks if the FTP server allows port scanning using the FTP bounce technique (FTP PORT command). This can be used to scan internal networks from the FTP server.', usage: 'nmap -sV --script ftp-bounce -p 21 <target>', args: ['ftp-bounce.username', 'ftp-bounce.password'], exampleOutput: '| ftp-bounce:\n|_  bounce working!', whenToUse: 'Test if an FTP server can be used as a bounce proxy to scan internal networks that are otherwise unreachable.' },
  { name: 'ftp-brute', category: 'brute', service: 'FTP', description: 'Performs brute force password guessing against FTP servers using username and password lists.', usage: 'nmap -sV --script ftp-brute -p 21 <target>', args: ['userdb - username wordlist', 'passdb - password wordlist'], exampleOutput: '| ftp-brute:\n|   Accounts:\n|     admin:password - Valid credentials\n|_    backup:backup123 - Valid credentials', whenToUse: 'Test FTP servers for weak credentials. Common targets include admin, root, backup, and service accounts.' },
  { name: 'ftp-vsftpd-backdoor', category: 'vuln', service: 'FTP', description: 'Tests for the backdoor in vsftpd 2.3.4 (CVE-2011-2523). A smiley face :) in the username triggers a shell on port 6200.', usage: 'nmap -sV --script ftp-vsftpd-backdoor -p 21 <target>', args: [], exampleOutput: '| ftp-vsftpd-backdoor:\n|   VULNERABLE:\n|   vsFTPd version 2.3.4 backdoor\n|     State: VULNERABLE\n|_    Shell on port 6200', whenToUse: 'Quick check on any vsftpd server. The backdoored version 2.3.4 is still found in legacy environments and CTFs.' },
  { name: 'ftp-proftpd-backdoor', category: 'vuln', service: 'FTP', description: 'Tests for the backdoor in ProFTPD 1.3.3c that was inserted in the source code distribution between November 28 and December 2, 2010.', usage: 'nmap -sV --script ftp-proftpd-backdoor -p 21 <target>', args: [], exampleOutput: '| ftp-proftpd-backdoor:\n|   VULNERABLE:\n|_  ProFTPD 1.3.3c backdoor', whenToUse: 'Test ProFTPD installations for the backdoor inserted via a supply chain compromise of the source code.' },
  { name: 'ftp-syst', category: 'default', service: 'FTP', description: 'Sends the FTP SYST command to determine the operating system type of the FTP server.', usage: 'nmap -sV --script ftp-syst -p 21 <target>', args: [], exampleOutput: '| ftp-syst:\n|_  SYST: UNIX Type: L8', whenToUse: 'Quickly identify the OS type of an FTP server for further targeted testing.' },

  // ===== DNS SCRIPTS =====
  { name: 'dns-brute', category: 'discovery', service: 'DNS', description: 'Performs DNS subdomain brute force enumeration using a built-in or custom wordlist. Attempts to resolve hostnames to discover subdomains.', usage: 'nmap -sV --script dns-brute --script-args dns-brute.domain=target.com <target>', args: ['dns-brute.domain - target domain', 'dns-brute.threads - number of threads', 'dns-brute.hostlist - custom subdomain wordlist', 'dns-brute.srvlist - SRV record list'], exampleOutput: '| dns-brute:\n|   DNS Brute-force hostnames:\n|     mail.target.com - 10.0.0.10\n|     vpn.target.com - 10.0.0.20\n|     dev.target.com - 10.0.0.30\n|_    staging.target.com - 10.0.0.40', whenToUse: 'Enumerate subdomains of a target domain. Useful for discovering additional attack surface like dev, staging, and internal services.' },
  { name: 'dns-zone-transfer', category: 'discovery', service: 'DNS', description: 'Requests a DNS zone transfer (AXFR) from a DNS server. If successful, reveals all DNS records in the zone, providing complete network mapping.', usage: 'nmap -sV --script dns-zone-transfer --script-args dns-zone-transfer.domain=target.com -p 53 <target>', args: ['dns-zone-transfer.domain - domain to transfer'], exampleOutput: '| dns-zone-transfer:\n|   target.com. SOA ns1.target.com.\n|   target.com. A 10.0.0.1\n|   mail.target.com. A 10.0.0.10\n|   db.target.com. A 10.0.0.50\n|_  internal.target.com. A 192.168.1.100', whenToUse: 'Test if DNS servers allow zone transfers. A successful transfer exposes the entire DNS zone, revealing internal hosts and network layout.' },
  { name: 'dns-cache-snoop', category: 'discovery', service: 'DNS', description: 'Performs DNS cache snooping against a DNS server to determine which domains the server has recently resolved, revealing browsing patterns.', usage: 'nmap -sV --script dns-cache-snoop --script-args dns-cache-snoop.mode=timed,dns-cache-snoop.domains=example.com -p 53 <target>', args: ['dns-cache-snoop.mode - nonrecursive or timed', 'dns-cache-snoop.domains - domains to check'], exampleOutput: '| dns-cache-snoop:\n|   1 of 1 domains found cached:\n|_    evil-site.com', whenToUse: 'Determine what domains users behind a DNS resolver have been visiting. Can reveal malware C2 domains or policy violations.' },
  { name: 'dns-recursion', category: 'default', service: 'DNS', description: 'Checks if a DNS server allows recursive queries. Open DNS resolvers can be abused for DNS amplification DDoS attacks.', usage: 'nmap -sV --script dns-recursion -p 53 <target>', args: [], exampleOutput: '| dns-recursion:\n|_  Recursion appears to be enabled', whenToUse: 'Identify open DNS resolvers that allow recursive queries from any source. These can be abused for DNS amplification attacks.' },
  { name: 'dns-nsid', category: 'discovery', service: 'DNS', description: 'Retrieves information from a DNS server by requesting its Name Server ID (NSID). Can reveal server hostname, version, or location.', usage: 'nmap -sV --script dns-nsid -p 53 <target>', args: [], exampleOutput: '| dns-nsid:\n|_  NSID: ns1.target.com (BIND 9.16.1)', whenToUse: 'Identify the DNS server software and version for vulnerability research.' },
  { name: 'dns-srv-enum', category: 'discovery', service: 'DNS', description: 'Enumerates various common SRV records for a given domain name, which can reveal internal services like Kerberos, LDAP, SIP, and XMPP.', usage: 'nmap -sV --script dns-srv-enum --script-args dns-srv-enum.domain=target.com <target>', args: ['dns-srv-enum.domain - target domain'], exampleOutput: '| dns-srv-enum:\n|   _ldap._tcp.target.com: dc01.target.com:389\n|   _kerberos._tcp.target.com: dc01.target.com:88\n|_  _sip._tcp.target.com: sip.target.com:5060', whenToUse: 'Discover internal services exposed via DNS SRV records, including domain controllers, Kerberos, and VoIP.' },

  // ===== SNMP SCRIPTS =====
  { name: 'snmp-brute', category: 'brute', service: 'SNMP', description: 'Attempts to find valid SNMP community strings by brute forcing common and custom community string lists.', usage: 'nmap -sU --script snmp-brute -p 161 <target>', args: ['snmp-brute.communitiesdb - custom community string list'], exampleOutput: '| snmp-brute:\n|   public - Valid credentials\n|_  private - Valid credentials', whenToUse: 'Test SNMP services for default or weak community strings. Common strings include public, private, manager, cisco, and community.' },
  { name: 'snmp-info', category: 'default', service: 'SNMP', description: 'Extracts basic information from an SNMP server including system description, contact, name, location, and uptime.', usage: 'nmap -sU --script snmp-info -p 161 <target>', args: [], exampleOutput: '| snmp-info:\n|   enterprise: net-snmp\n|   engineIDFormat: unknown\n|   contact: admin@target.com\n|   name: router01\n|   location: Server Room A\n|_  uptime: 45 days 12:30:00', whenToUse: 'Extract system information via SNMP. Can reveal hardware/software details, system name, and administrator contact info.' },
  { name: 'snmp-interfaces', category: 'discovery', service: 'SNMP', description: 'Enumerates network interfaces through SNMP, revealing IP addresses, MAC addresses, interface types, and status of all network interfaces.', usage: 'nmap -sU --script snmp-interfaces -p 161 <target>', args: [], exampleOutput: '| snmp-interfaces:\n|   eth0\n|     IP: 10.0.0.1/24\n|     MAC: aa:bb:cc:dd:ee:ff\n|     Status: up\n|   eth1\n|     IP: 192.168.1.1/24\n|_    Status: up', whenToUse: 'Discover all network interfaces and IP addresses on a device. Reveals dual-homed hosts and internal network ranges.' },
  { name: 'snmp-processes', category: 'discovery', service: 'SNMP', description: 'Enumerates running processes on a system through SNMP, showing process names, IDs, and resource usage.', usage: 'nmap -sU --script snmp-processes -p 161 <target>', args: [], exampleOutput: '| snmp-processes:\n|   1: init\n|   400: sshd\n|   500: apache2\n|_  600: mysqld', whenToUse: 'Enumerate running processes via SNMP to identify services, security software, and potential targets.' },
  { name: 'snmp-sysdescr', category: 'default', service: 'SNMP', description: 'Retrieves the sysDescr.0 MIB value from an SNMP server, which typically contains the operating system name and version.', usage: 'nmap -sU --script snmp-sysdescr -p 161 <target>', args: [], exampleOutput: '| snmp-sysdescr:\n|_  Linux router01 5.4.0-42-generic #46-Ubuntu SMP', whenToUse: 'Quick OS identification through SNMP sysDescr string. Often reveals exact OS version and kernel.' },
  { name: 'snmp-netstat', category: 'discovery', service: 'SNMP', description: 'Enumerates network connections (open ports and established connections) through SNMP, similar to running netstat on the target.', usage: 'nmap -sU --script snmp-netstat -p 161 <target>', args: [], exampleOutput: '| snmp-netstat:\n|   TCP  0.0.0.0:22     0.0.0.0:0      LISTEN\n|   TCP  10.0.0.1:443   10.0.0.50:54321 ESTABLISHED\n|_  UDP  0.0.0.0:161    *:*', whenToUse: 'Discover listening ports and active connections via SNMP. Can reveal services not found by port scanning.' },

  // ===== SMTP SCRIPTS =====
  { name: 'smtp-enum-users', category: 'discovery', service: 'SMTP', description: 'Enumerates valid email addresses on an SMTP server using VRFY, EXPN, and RCPT TO commands to determine which users exist.', usage: 'nmap -sV --script smtp-enum-users --script-args smtp-enum-users.methods={VRFY,EXPN,RCPT} -p 25 <target>', args: ['smtp-enum-users.methods - methods to use', 'smtp-enum-users.domain - domain to append'], exampleOutput: '| smtp-enum-users:\n|   root\n|   admin\n|   info\n|   webmaster\n|_  postmaster', whenToUse: 'Enumerate valid email addresses for phishing target lists or credential attacks. Many servers disable VRFY/EXPN but RCPT TO may still work.' },
  { name: 'smtp-commands', category: 'default', service: 'SMTP', description: 'Attempts to use EHLO and HELP to gather the SMTP commands supported by a mail server, including extended features and authentication methods.', usage: 'nmap -sV --script smtp-commands -p 25 <target>', args: [], exampleOutput: '| smtp-commands:\n|   EHLO response:\n|     SIZE 52428800\n|     STARTTLS\n|     AUTH PLAIN LOGIN\n|     ENHANCEDSTATUSCODES\n|_    8BITMIME', whenToUse: 'Identify SMTP server capabilities including authentication methods, max message size, and TLS support.' },
  { name: 'smtp-open-relay', category: 'vuln', service: 'SMTP', description: 'Checks if an SMTP server is configured as an open relay, which would allow sending emails through it without authentication.', usage: 'nmap -sV --script smtp-open-relay -p 25 <target>', args: ['smtp-open-relay.from - from address', 'smtp-open-relay.to - to address'], exampleOutput: '| smtp-open-relay:\n|   Server is an open relay (16/16 tests passed)\n|_  Relay allowed for all tested patterns', whenToUse: 'Test if a mail server is an open relay. Open relays can be abused for spam and phishing. This is a common compliance check.' },
  { name: 'smtp-vuln-cve2010-4344', category: 'vuln', service: 'SMTP', description: 'Tests for a heap-based buffer overflow vulnerability in Exim SMTP server (CVE-2010-4344) that allows remote code execution.', usage: 'nmap -sV --script smtp-vuln-cve2010-4344 -p 25 <target>', args: [], exampleOutput: '| smtp-vuln-cve2010-4344:\n|   VULNERABLE\n|_  Exim heap-based buffer overflow', whenToUse: 'Test Exim mail servers for this critical RCE vulnerability. Affects Exim versions before 4.72.' },

  // ===== MySQL SCRIPTS =====
  { name: 'mysql-brute', category: 'brute', service: 'MySQL', description: 'Performs brute force password guessing against MySQL server using username and password wordlists.', usage: 'nmap -sV --script mysql-brute -p 3306 <target>', args: ['userdb - username wordlist', 'passdb - password wordlist'], exampleOutput: '| mysql-brute:\n|   Accounts:\n|     root:root - Valid credentials\n|_    admin:admin123 - Valid credentials', whenToUse: 'Test MySQL servers for weak credentials. Common accounts include root, admin, mysql, and application-specific users.' },
  { name: 'mysql-databases', category: 'discovery', service: 'MySQL', description: 'Lists all databases on a MySQL server that the authenticated user has access to.', usage: 'nmap -sV --script mysql-databases --script-args mysqluser=root,mysqlpass=password -p 3306 <target>', args: ['mysqluser - MySQL username', 'mysqlpass - MySQL password'], exampleOutput: '| mysql-databases:\n|   information_schema\n|   mysql\n|   performance_schema\n|   webapp_db\n|_  customer_data', whenToUse: 'Enumerate MySQL databases after obtaining valid credentials. Identify databases containing sensitive data.' },
  { name: 'mysql-empty-password', category: 'vuln', service: 'MySQL', description: 'Checks if the MySQL root account has an empty password, which is a common misconfiguration especially in development environments.', usage: 'nmap -sV --script mysql-empty-password -p 3306 <target>', args: [], exampleOutput: '| mysql-empty-password:\n|_  root account has empty password', whenToUse: 'Quick check for MySQL root accounts with no password. Very common in development and test environments.' },
  { name: 'mysql-info', category: 'default', service: 'MySQL', description: 'Connects to a MySQL server and retrieves version information, protocol version, capabilities, status, and salt.', usage: 'nmap -sV --script mysql-info -p 3306 <target>', args: [], exampleOutput: '| mysql-info:\n|   Protocol: 10\n|   Version: 8.0.28-0ubuntu0.20.04.3\n|   Thread ID: 15\n|   Capabilities: Long Passwords, Connect with DB, Compress\n|_  Salt: abc123def456ghi789', whenToUse: 'Identify MySQL version and capabilities for vulnerability assessment and exploit selection.' },
  { name: 'mysql-users', category: 'discovery', service: 'MySQL', description: 'Lists MySQL user accounts and their authentication hosts when accessed with sufficient privileges.', usage: 'nmap -sV --script mysql-users --script-args mysqluser=root,mysqlpass=password -p 3306 <target>', args: ['mysqluser', 'mysqlpass'], exampleOutput: '| mysql-users:\n|   root@localhost\n|   root@%\n|   webapp@10.0.0.%\n|_  backup@localhost', whenToUse: 'Enumerate MySQL user accounts to identify potential targets and understand access patterns.' },
  { name: 'mysql-audit', category: 'discovery', service: 'MySQL', description: 'Audits MySQL database server security configuration against the CIS MySQL benchmark, checking for common security issues.', usage: 'nmap -sV --script mysql-audit --script-args mysql-audit.username=root,mysql-audit.password=pass -p 3306 <target>', args: ['mysql-audit.username', 'mysql-audit.password', 'mysql-audit.filename - CIS benchmark file'], exampleOutput: '| mysql-audit:\n|   CIS MySQL Benchmarks v1.0.2:\n|     3.1: FAIL - Skip networking disabled\n|     3.2: PASS - Symbolic links disabled\n|_    4.1: FAIL - Root can login remotely', whenToUse: 'Comprehensive MySQL security audit against CIS benchmarks. Check after gaining MySQL access during pentests.' },

  // ===== MSSQL SCRIPTS =====
  { name: 'ms-sql-brute', category: 'brute', service: 'MSSQL', description: 'Performs brute force password guessing against Microsoft SQL Server using username and password lists.', usage: 'nmap -sV --script ms-sql-brute -p 1433 <target>', args: ['userdb', 'passdb', 'ms-sql-brute.brute-windows-accounts - try Windows accounts'], exampleOutput: '| ms-sql-brute:\n|   Accounts:\n|     sa:sa - Valid credentials\n|_    admin:password123 - Valid credentials', whenToUse: 'Test MSSQL servers for weak credentials. The sa (System Administrator) account is the primary target.' },
  { name: 'ms-sql-info', category: 'default', service: 'MSSQL', description: 'Extracts information from Microsoft SQL Server instances, including version, service pack, and instance names.', usage: 'nmap -sV --script ms-sql-info -p 1433 <target>', args: [], exampleOutput: '| ms-sql-info:\n|   Instance name: MSSQLSERVER\n|   Version: Microsoft SQL Server 2019\n|     Number: 15.0.2000.5\n|   TCP port: 1433\n|_  Clustered: No', whenToUse: 'Identify MSSQL version and instance information for vulnerability assessment.' },
  { name: 'ms-sql-empty-password', category: 'vuln', service: 'MSSQL', description: 'Checks if the MSSQL sa account has an empty password, a common misconfiguration in development environments.', usage: 'nmap -sV --script ms-sql-empty-password -p 1433 <target>', args: [], exampleOutput: '| ms-sql-empty-password:\n|_  sa account has empty password', whenToUse: 'Quick check for MSSQL sa accounts with no password.' },
  { name: 'ms-sql-xp-cmdshell', category: 'exploit', service: 'MSSQL', description: 'Attempts to execute commands via xp_cmdshell on a Microsoft SQL Server. xp_cmdshell allows execution of operating system commands from within SQL Server.', usage: 'nmap -sV --script ms-sql-xp-cmdshell --script-args mssql.username=sa,mssql.password=pass,ms-sql-xp-cmdshell.cmd="whoami" -p 1433 <target>', args: ['mssql.username', 'mssql.password', 'ms-sql-xp-cmdshell.cmd - command to execute'], exampleOutput: '| ms-sql-xp-cmdshell:\n|   Command: whoami\n|   Output:\n|_    nt service\\mssqlserver', whenToUse: 'Execute OS commands through MSSQL xp_cmdshell. This is a critical post-exploitation technique for MSSQL.' },

  // ===== RDP SCRIPTS =====
  { name: 'rdp-enum-encryption', category: 'discovery', service: 'RDP', description: 'Determines which RDP encryption levels and security protocols (Standard RDP, TLS, CredSSP/NLA) are supported by the target.', usage: 'nmap -sV --script rdp-enum-encryption -p 3389 <target>', args: [], exampleOutput: '| rdp-enum-encryption:\n|   Security layer\n|     Native RDP: SUCCESS\n|     TLS: SUCCESS\n|     CredSSP (NLA): SUCCESS\n|   RDP Encryption level: Client Compatible\n|_  RDP Protocol Version: Unknown', whenToUse: 'Assess RDP security configuration. NLA (Network Level Authentication) should be required. Standard RDP encryption without TLS is vulnerable.' },
  { name: 'rdp-vuln-ms12-020', category: 'vuln', service: 'RDP', description: 'Tests for the MS12-020 RDP vulnerability (CVE-2012-0002) which can cause a denial of service (Blue Screen of Death) on vulnerable Windows systems.', usage: 'nmap -sV --script rdp-vuln-ms12-020 -p 3389 <target>', args: [], exampleOutput: '| rdp-vuln-ms12-020:\n|   VULNERABLE:\n|   MS12-020 Remote Desktop Protocol Vulnerability\n|_    State: VULNERABLE', whenToUse: 'Test for this DoS vulnerability on older Windows systems with RDP exposed. Handle with care as exploitation causes BSOD.' },
  { name: 'rdp-ntlm-info', category: 'discovery', service: 'RDP', description: 'Extracts NTLM authentication information from an RDP server, including hostname, domain name, DNS names, and OS version.', usage: 'nmap -sV --script rdp-ntlm-info -p 3389 <target>', args: [], exampleOutput: '| rdp-ntlm-info:\n|   Target Name: CORP\n|   NetBIOS Domain: CORP\n|   NetBIOS Computer: WS01\n|   DNS Domain: corp.local\n|   DNS Computer: ws01.corp.local\n|_  OS: Windows 10 Build 19041', whenToUse: 'Extract domain and hostname info from RDP without authentication. Useful for domain enumeration and OS fingerprinting.' },

  // ===== VNC SCRIPTS =====
  { name: 'vnc-brute', category: 'brute', service: 'VNC', description: 'Performs brute force password guessing against VNC servers. VNC typically uses a single shared password rather than username/password.', usage: 'nmap -sV --script vnc-brute -p 5900 <target>', args: ['passdb - password wordlist'], exampleOutput: '| vnc-brute:\n|   Found password: password\n|_  State: Valid credentials', whenToUse: 'Test VNC servers for weak passwords. VNC uses a single password for authentication, making it easier to brute force.' },
  { name: 'vnc-info', category: 'default', service: 'VNC', description: 'Queries a VNC server for its protocol version and supported security types, revealing authentication mechanisms used.', usage: 'nmap -sV --script vnc-info -p 5900 <target>', args: [], exampleOutput: '| vnc-info:\n|   Protocol version: 3.8\n|   Security types:\n|     VNC Authentication (2)\n|_    Tight (16)', whenToUse: 'Identify VNC protocol version and security configuration. Some versions support no authentication.' },

  // ===== LDAP SCRIPTS =====
  { name: 'ldap-rootdse', category: 'discovery', service: 'LDAP', description: 'Retrieves the LDAP root DSE (Directory Server Agent specific Entry) which reveals naming contexts, supported controls, extensions, and server capabilities.', usage: 'nmap -sV --script ldap-rootdse -p 389 <target>', args: [], exampleOutput: '| ldap-rootdse:\n|   namingContexts: DC=corp,DC=local\n|   defaultNamingContext: DC=corp,DC=local\n|   serverName: CN=DC01,CN=Servers,CN=Default-First-Site-Name\n|   dnsHostName: dc01.corp.local\n|_  forestFunctionality: 7 (2016)', whenToUse: 'Enumerate LDAP server information including domain name, domain controller identity, and forest functional level.' },
  { name: 'ldap-search', category: 'discovery', service: 'LDAP', description: 'Performs LDAP search queries to enumerate objects in the directory, including users, groups, computers, and organizational units.', usage: 'nmap -sV --script ldap-search --script-args ldap.base="dc=corp,dc=local",ldap.attrib="cn,mail,description" -p 389 <target>', args: ['ldap.base - search base DN', 'ldap.attrib - attributes to retrieve', 'ldap.username', 'ldap.password'], exampleOutput: '| ldap-search:\n|   Context: DC=corp,DC=local\n|     dn: CN=John Doe,OU=Users,DC=corp,DC=local\n|       cn: John Doe\n|       mail: john.doe@corp.local\n|     dn: CN=Admin,OU=Admins,DC=corp,DC=local\n|_      cn: Admin', whenToUse: 'Enumerate Active Directory objects via LDAP. Extract user lists, group memberships, computer accounts, and more.' },
  { name: 'ldap-brute', category: 'brute', service: 'LDAP', description: 'Attempts to brute force LDAP authentication using common username and password combinations.', usage: 'nmap -sV --script ldap-brute -p 389 <target>', args: ['userdb', 'passdb', 'ldap.base'], exampleOutput: '| ldap-brute:\n|   CN=admin,DC=corp,DC=local:password123 - Valid credentials\n|_  CN=svc_backup,DC=corp,DC=local:backup! - Valid credentials', whenToUse: 'Test LDAP bind credentials. Use with caution as Active Directory has lockout policies.' },

  // ===== KERBEROS SCRIPTS =====
  { name: 'krb5-enum-users', category: 'discovery', service: 'Kerberos', description: 'Enumerates valid Active Directory usernames by sending Kerberos AS-REQ messages. Valid users receive a different error code than invalid ones.', usage: 'nmap -sV --script krb5-enum-users --script-args krb5-enum-users.realm=CORP.LOCAL,userdb=users.txt -p 88 <target>', args: ['krb5-enum-users.realm - Kerberos realm', 'userdb - username wordlist'], exampleOutput: '| krb5-enum-users:\n|   Discovered Kerberos principals:\n|     administrator@CORP.LOCAL\n|     svc_sql@CORP.LOCAL\n|_    john.doe@CORP.LOCAL', whenToUse: 'Enumerate valid Active Directory usernames without authentication. Does not trigger logon failures or account lockouts.' },

  // ===== NFS SCRIPTS =====
  { name: 'nfs-ls', category: 'discovery', service: 'NFS', description: 'Lists files and directories on NFS exports accessible from the scanner. Reveals file permissions and ownership.', usage: 'nmap -sV --script nfs-ls -p 2049 <target>', args: [], exampleOutput: '| nfs-ls:\n|   Volume /backup\n|     drwxrwxrwx root root  4096 backup/\n|     -rw-r--r-- root root  1.2G db_backup.sql\n|_    -rw------- root root  256K shadow.bak', whenToUse: 'List files on NFS exports. Look for sensitive files like backups, configuration files, or credential files.' },
  { name: 'nfs-showmount', category: 'discovery', service: 'NFS', description: 'Lists NFS exports and which hosts are allowed to mount them. Equivalent to running showmount -e on the target.', usage: 'nmap -sV --script nfs-showmount -p 111,2049 <target>', args: [], exampleOutput: '| nfs-showmount:\n|   /backup 10.0.0.0/24\n|   /home *\n|_  /var/www (everyone)', whenToUse: 'Identify NFS exports and access controls. Exports available to * (everyone) or broad subnets are common misconfigurations.' },
  { name: 'nfs-statfs', category: 'discovery', service: 'NFS', description: 'Retrieves disk space statistics from NFS exports including total size, used space, and available space.', usage: 'nmap -sV --script nfs-statfs -p 2049 <target>', args: [], exampleOutput: '| nfs-statfs:\n|   Filesystem  Size    Used    Avail   Use%\n|_  /backup     500G    320G    180G    64%', whenToUse: 'Check NFS export disk usage. Large used space may indicate valuable data storage.' },

  // ===== TELNET SCRIPTS =====
  { name: 'telnet-brute', category: 'brute', service: 'Telnet', description: 'Performs brute force password guessing against Telnet servers using username and password wordlists.', usage: 'nmap -sV --script telnet-brute -p 23 <target>', args: ['userdb', 'passdb'], exampleOutput: '| telnet-brute:\n|   Accounts:\n|_    admin:admin - Valid credentials', whenToUse: 'Test Telnet services for weak credentials. Telnet is inherently insecure (cleartext) and should be replaced with SSH.' },
  { name: 'telnet-encryption', category: 'discovery', service: 'Telnet', description: 'Determines whether the Telnet server supports encryption (TelOpt ENCRYPT). Most Telnet implementations do not support encryption.', usage: 'nmap -sV --script telnet-encryption -p 23 <target>', args: [], exampleOutput: '| telnet-encryption:\n|_  Telnet server does not support encryption', whenToUse: 'Verify that Telnet connections are not encrypted, confirming the risk of cleartext credential transmission.' },

  // ===== VULNERABILITY SCRIPTS (GENERAL) =====
  { name: 'vulners', category: 'vuln', service: 'General', description: 'Uses the vulners.com API to query for known vulnerabilities based on detected service versions. One of the most useful NSE scripts for vulnerability assessment.', usage: 'nmap -sV --script vulners -p- <target>', args: ['vulners.mincvss - minimum CVSS score to show'], exampleOutput: '| vulners:\n|   cpe:/a:apache:http_server:2.4.29:\n|     CVE-2019-0211  7.2  https://vulners.com/cve/CVE-2019-0211\n|     CVE-2019-0196  5.0  https://vulners.com/cve/CVE-2019-0196\n|_    CVE-2018-17199 5.0  https://vulners.com/cve/CVE-2018-17199', whenToUse: 'Quick vulnerability assessment based on detected service versions. Run after service version detection (-sV) for best results.' },
  { name: 'vulscan', category: 'vuln', service: 'General', description: 'Advanced vulnerability scanner that uses multiple offline CVE databases to match detected service versions against known vulnerabilities.', usage: 'nmap -sV --script vulscan/vulscan.nse -p- <target>', args: ['vulscan.updatedb - update vulnerability databases'], exampleOutput: '| vulscan:\n|   [CVE-2021-44228] Apache Log4j2 2.x JNDI RCE (CVSS: 10.0)\n|   [CVE-2019-0211] Apache httpd privilege escalation (CVSS: 7.2)', whenToUse: 'More comprehensive vulnerability scanning than vulners. Uses offline databases so works without internet access.' },
  { name: 'ssl-heartbleed', category: 'vuln', service: 'SSL/TLS', description: 'Tests for the OpenSSL Heartbleed vulnerability (CVE-2014-0160) which allows reading memory from the server, potentially exposing private keys and session data.', usage: 'nmap -sV --script ssl-heartbleed -p 443 <target>', args: [], exampleOutput: '| ssl-heartbleed:\n|   VULNERABLE:\n|   The Heartbleed Bug (CVE-2014-0160)\n|     State: VULNERABLE\n|     Risk factor: High\n|     Description: OpenSSL versions 1.0.1 through 1.0.1f contain a flaw in TLS heartbeat handling', whenToUse: 'Test any SSL/TLS service for Heartbleed. While mostly patched, legacy systems may still be vulnerable.' },
  { name: 'ssl-poodle', category: 'vuln', service: 'SSL/TLS', description: 'Tests for the POODLE vulnerability (CVE-2014-3566) in SSLv3, which allows decryption of encrypted traffic through a padding oracle attack.', usage: 'nmap -sV --script ssl-poodle -p 443 <target>', args: [], exampleOutput: '| ssl-poodle:\n|   VULNERABLE:\n|   SSL POODLE information leak\n|_    State: VULNERABLE', whenToUse: 'Check if SSLv3 is still enabled on TLS services. SSLv3 should be completely disabled on all services.' },
  { name: 'ssl-enum-ciphers', category: 'discovery', service: 'SSL/TLS', description: 'Enumerates SSL/TLS cipher suites supported by the server, organized by protocol version (SSLv3, TLS 1.0, 1.1, 1.2, 1.3), with strength ratings.', usage: 'nmap -sV --script ssl-enum-ciphers -p 443 <target>', args: [], exampleOutput: '| ssl-enum-ciphers:\n|   TLSv1.2:\n|     ciphers:\n|       TLS_ECDHE_RSA_WITH_AES_256_GCM_SHA384 (ecdh_x25519) - A\n|       TLS_ECDHE_RSA_WITH_AES_128_GCM_SHA256 (ecdh_x25519) - A\n|     compressors: NULL\n|     cipher preference: server\n|_  least strength: A', whenToUse: 'Comprehensive TLS configuration audit. Identify weak ciphers, outdated protocols, and missing security features.' },
  { name: 'ssl-cert', category: 'default', service: 'SSL/TLS', description: 'Retrieves and displays the SSL/TLS certificate of a server, including subject, issuer, validity dates, and Subject Alternative Names.', usage: 'nmap -sV --script ssl-cert -p 443 <target>', args: [], exampleOutput: '| ssl-cert:\n|   Subject: commonName=www.target.com\n|   Subject Alternative Names:\n|     DNS:www.target.com\n|     DNS:target.com\n|     DNS:mail.target.com\n|   Issuer: commonName=Lets Encrypt Authority X3\n|   Validity:\n|     Not Before: 2024-01-01\n|_    Not After:  2024-04-01', whenToUse: 'Examine SSL/TLS certificates for expiration, weak algorithms, hostname mismatches, and SAN enumeration for additional hostnames.' },
  { name: 'ssl-dh-params', category: 'vuln', service: 'SSL/TLS', description: 'Tests for weak Diffie-Hellman key exchange parameters, including Logjam (CVE-2015-4000) which uses export-grade 512-bit DH parameters.', usage: 'nmap -sV --script ssl-dh-params -p 443 <target>', args: [], exampleOutput: '| ssl-dh-params:\n|   VULNERABLE:\n|   Diffie-Hellman Key Exchange Insufficient Group Strength\n|_    State: VULNERABLE (1024-bit)', whenToUse: 'Check for weak DH parameters. Groups smaller than 2048-bit are considered weak. 512-bit (export grade) is exploitable.' },

  // ===== MISCELLANEOUS SCRIPTS =====
  { name: 'banner', category: 'default', service: 'General', description: 'Connects to a TCP port and prints anything sent by the listening service within a few seconds. Useful for grabbing service banners.', usage: 'nmap -sV --script banner -p <port> <target>', args: ['banner.timeout - how long to wait for banner'], exampleOutput: '| banner:\n|_  220 mail.target.com ESMTP Postfix', whenToUse: 'Grab service banners from any TCP port. Useful for services that nmap service detection does not recognize.' },
  { name: 'nbstat', category: 'discovery', service: 'NetBIOS', description: 'Queries the target for NetBIOS names, revealing computer name, domain/workgroup, logged-in users, and MAC address.', usage: 'nmap -sU --script nbstat -p 137 <target>', args: [], exampleOutput: '| nbstat:\n|   NetBIOS name: WS01\n|   NetBIOS user: ADMIN\n|   NetBIOS MAC: aa:bb:cc:dd:ee:ff\n|_  Names:\n|     WS01<00>   Flags: <unique><active>\n|     CORP<00>    Flags: <group><active>', whenToUse: 'Enumerate NetBIOS information from Windows hosts, including computer names and domain membership.' },
  { name: 'broadcast-dhcp-discover', category: 'broadcast', service: 'DHCP', description: 'Sends a DHCP discover broadcast and reports the responses, revealing DHCP server addresses, offered IPs, gateway, DNS, and subnet information.', usage: 'nmap --script broadcast-dhcp-discover', args: [], exampleOutput: '| broadcast-dhcp-discover:\n|   DHCP Server: 10.0.0.1\n|   Offered IP: 10.0.0.100\n|   Subnet: 255.255.255.0\n|   Router: 10.0.0.1\n|   DNS: 10.0.0.2\n|_  Domain: corp.local', whenToUse: 'Discover DHCP servers on the network and the configuration they offer. Identifies rogue DHCP servers.' },
  { name: 'ipmi-brute', category: 'brute', service: 'IPMI', description: 'Performs brute force password guessing against IPMI (Intelligent Platform Management Interface) 2.0 servers. IPMI provides out-of-band management.', usage: 'nmap -sU --script ipmi-brute -p 623 <target>', args: ['userdb', 'passdb'], exampleOutput: '| ipmi-brute:\n|   Accounts:\n|_    admin:ADMIN - Valid credentials', whenToUse: 'Test IPMI/BMC for weak credentials. Default credentials are very common on IPMI systems (admin/admin, ADMIN/ADMIN).' },
  { name: 'ipmi-cipher-zero', category: 'vuln', service: 'IPMI', description: 'Tests for IPMI Cipher 0 vulnerability which allows authentication bypass on IPMI 2.0 systems by using an unencrypted authentication type.', usage: 'nmap -sU --script ipmi-cipher-zero -p 623 <target>', args: [], exampleOutput: '| ipmi-cipher-zero:\n|   VULNERABLE:\n|   IPMI 2.0 Authentication Bypass via Cipher 0\n|_    State: VULNERABLE', whenToUse: 'Check IPMI 2.0 implementations for cipher zero bypass. This allows complete authentication bypass on many BMC implementations.' },
  { name: 'ipmi-version', category: 'default', service: 'IPMI', description: 'Identifies IPMI version and reports BMC (Baseboard Management Controller) information including firmware version and manufacturer.', usage: 'nmap -sU --script ipmi-version -p 623 <target>', args: [], exampleOutput: '| ipmi-version:\n|   Version: 2.0\n|   Manufacturer: Dell Inc.\n|_  Product: iDRAC 9', whenToUse: 'Identify IPMI/BMC version and manufacturer for vulnerability assessment of out-of-band management interfaces.' },
  { name: 'oracle-brute', category: 'brute', service: 'Oracle', description: 'Performs brute force password guessing against Oracle Database servers using SID and credential lists.', usage: 'nmap -sV --script oracle-brute --script-args oracle-brute.sid=ORCL -p 1521 <target>', args: ['oracle-brute.sid - Oracle SID', 'userdb', 'passdb'], exampleOutput: '| oracle-brute:\n|   Accounts:\n|_    SYSTEM/manager - Valid credentials', whenToUse: 'Test Oracle databases for weak credentials. Common accounts include SYS, SYSTEM, DBSNMP, SCOTT.' },
  { name: 'oracle-sid-brute', category: 'brute', service: 'Oracle', description: 'Brute forces Oracle TNS listener for valid SID (System Identifier) names. SIDs are needed to connect to Oracle databases.', usage: 'nmap -sV --script oracle-sid-brute -p 1521 <target>', args: [], exampleOutput: '| oracle-sid-brute:\n|   SIDs found:\n|     ORCL - Status: OK\n|     XE - Status: OK\n|_    PROD - Status: OK', whenToUse: 'Discover Oracle SIDs when they are not known. Required before attempting Oracle authentication brute force.' },
  { name: 'redis-brute', category: 'brute', service: 'Redis', description: 'Performs brute force password guessing against Redis servers. Many Redis instances are deployed without authentication.', usage: 'nmap -sV --script redis-brute -p 6379 <target>', args: ['passdb'], exampleOutput: '| redis-brute:\n|_  No password required', whenToUse: 'Test Redis instances for authentication. Many Redis servers are deployed without any password, allowing full access.' },
  { name: 'redis-info', category: 'discovery', service: 'Redis', description: 'Retrieves information from a Redis server including version, OS, memory usage, connected clients, and configuration.', usage: 'nmap -sV --script redis-info -p 6379 <target>', args: [], exampleOutput: '| redis-info:\n|   Version: 6.2.6\n|   OS: Linux 5.4.0-42-generic x86_64\n|   Arch: 64 bits\n|   Memory: 1.2M used\n|   Connected clients: 3\n|_  Config file: /etc/redis/redis.conf', whenToUse: 'Gather Redis server information. Look for unauthenticated access and potential for RCE through CONFIG SET.' },
  { name: 'mongodb-brute', category: 'brute', service: 'MongoDB', description: 'Performs brute force password guessing against MongoDB servers.', usage: 'nmap -sV --script mongodb-brute -p 27017 <target>', args: ['userdb', 'passdb', 'mongodb-brute.db'], exampleOutput: '| mongodb-brute:\n|   Accounts:\n|_    admin:password - Valid credentials', whenToUse: 'Test MongoDB for weak credentials. Many MongoDB instances are deployed without authentication enabled.' },
  { name: 'mongodb-databases', category: 'discovery', service: 'MongoDB', description: 'Lists all databases on a MongoDB server that the user has access to, including database names and sizes.', usage: 'nmap -sV --script mongodb-databases -p 27017 <target>', args: [], exampleOutput: '| mongodb-databases:\n|   admin - 0.1M\n|   local - 0.0M\n|   webapp - 2.3G\n|_  customers - 500M', whenToUse: 'Enumerate MongoDB databases. Unauthenticated access to MongoDB has been a massive source of data breaches.' },
  { name: 'cassandra-brute', category: 'brute', service: 'Cassandra', description: 'Performs brute force password guessing against Apache Cassandra database servers.', usage: 'nmap -sV --script cassandra-brute -p 9042 <target>', args: ['userdb', 'passdb'], exampleOutput: '| cassandra-brute:\n|   Accounts:\n|_    cassandra:cassandra - Valid credentials', whenToUse: 'Test Cassandra databases for default credentials (cassandra/cassandra is the default).' },
  { name: 'docker-version', category: 'discovery', service: 'Docker', description: 'Queries the Docker daemon API for version information. An exposed Docker API allows container escape and host takeover.', usage: 'nmap -sV --script docker-version -p 2375,2376 <target>', args: [], exampleOutput: '| docker-version:\n|   Version: 20.10.12\n|   API version: 1.41\n|   OS: linux\n|_  Arch: amd64', whenToUse: 'Check for exposed Docker APIs. An unauthenticated Docker API gives root-equivalent access to the host system.' },
  { name: 'pptp-version', category: 'discovery', service: 'PPTP', description: 'Retrieves version information from PPTP (Point-to-Point Tunneling Protocol) VPN servers including hostname, vendor, and firmware revision.', usage: 'nmap -sV --script pptp-version -p 1723 <target>', args: [], exampleOutput: '| pptp-version:\n|   Hostname: VPN-Server\n|   Vendor: Microsoft\n|_  Firmware: 1.0', whenToUse: 'Identify PPTP VPN servers. PPTP is considered insecure and should be replaced with modern VPN protocols.' },
  { name: 'sip-methods', category: 'discovery', service: 'SIP', description: 'Enumerates methods supported by a SIP (Session Initiation Protocol) server by sending an OPTIONS request.', usage: 'nmap -sV --script sip-methods -p 5060 <target>', args: [], exampleOutput: '| sip-methods:\n|   Supported methods:\n|_    INVITE, ACK, CANCEL, OPTIONS, BYE, REFER, SUBSCRIBE, NOTIFY, INFO', whenToUse: 'Enumerate SIP server capabilities for VoIP security assessments.' },
  { name: 'sip-brute', category: 'brute', service: 'SIP', description: 'Performs brute force password guessing against SIP (VoIP) accounts.', usage: 'nmap -sV --script sip-brute -p 5060 <target>', args: ['userdb', 'passdb'], exampleOutput: '| sip-brute:\n|   Accounts:\n|_    100:1234 - Valid credentials', whenToUse: 'Test SIP/VoIP systems for weak extension passwords. Extensions are often sequential numbers (100-199) with simple PINs.' },
];
